"""Tests for the guarded Dependabot lock repair publisher."""

import base64
import importlib.util
import json
import os
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch


SPEC = importlib.util.spec_from_file_location(
    "validate_dependabot_locks", Path(__file__).resolve().parents[1] / "validate-dependabot-locks.py"
)
validate = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(validate)
HEADER = b"# This file is autogenerated by pip-compile with Python 3.11\n"
HASH = b"    --hash=sha256:" + b"a" * 64
BEFORE = HEADER + b"example==1.0 \\\n" + HASH + b" \\\n" + HASH + b"\n"
AFTER = HEADER + b"example==1.0 \\\n" + HASH + b"\n"


class LockRepairTests(unittest.TestCase):
    def test_repairs_only_allowlisted_modified_locks_across_pages(self):
        paths = ["requirements.txt", "docs/requirements.txt", "projects/service/requirements/dev.txt"]
        pages = [
            [{"filename": "requirements.txt", "status": "added"},
             {"filename": "hidden.txt", "status": "modified", "sha": "hidden"}],
            [{"filename": paths[2], "status": "modified", "sha": "service"}],
        ]
        with patch.object(validate.subprocess, "check_output", return_value=json.dumps(pages)), \
             patch.object(validate, "lock_contents", return_value=BEFORE) as read:
            self.assertEqual(validate.repair_changed_locks("org/repo", "17", "head", paths), {paths[2]: AFTER})
        read.assert_called_once_with("org/repo", paths[2], "head", "service")

    def test_rejects_unsafe_path_before_accessing_github(self):
        with patch.object(validate.subprocess, "check_output") as request:
            with self.assertRaisesRegex(SystemExit, "Invalid hash-only lock paths"):
                validate.repair_changed_locks("org/repo", "17", "head", ["docs/../requirements.txt"])
        request.assert_not_called()

    def test_rejects_files_without_generated_header(self):
        pages = [[{"filename": "requirements.txt", "status": "modified", "sha": "file"}]]
        with patch.object(validate.subprocess, "check_output", return_value=json.dumps(pages)), \
             patch.object(validate, "lock_contents", return_value=BEFORE[len(HEADER):]):
            with self.assertRaisesRegex(SystemExit, "not a generated pip-compile lock"):
                validate.repair_changed_locks("org/repo", "17", "head", ["requirements.txt"])

    def test_rejects_blob_mismatch(self):
        response = {"type": "file", "encoding": "base64", "content": base64.b64encode(BEFORE), "sha": "different"}
        with patch.object(validate, "api", return_value=response):
            with self.assertRaisesRegex(SystemExit, "Cannot verify"):
                validate.lock_contents("org/repo", "requirements.txt", "head", "expected")

    def test_legacy_mode_accepts_duplicates_only_and_rejects_pin_drift(self):
        with tempfile.TemporaryDirectory() as temp:
            folder = Path(temp) / "regenerated-locks"
            folder.mkdir()
            lock = folder / "dev.txt"
            lock.write_bytes(AFTER)
            with patch.dict(os.environ, RUNNER_TEMP=temp), patch.object(validate, "lock_contents", return_value=BEFORE):
                self.assertEqual(validate.validate_regenerated_locks("org/repo", "head", ["dev"], "base"),
                                 {"requirements/dev.txt": AFTER})
                lock.write_bytes(AFTER.replace(b"1.0", b"2.0"))
                with self.assertRaisesRegex(SystemExit, "unexpected changes"):
                    validate.validate_regenerated_locks("org/repo", "head", ["dev"], "base")
